INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(33411, 'John 4:42', 'John', 4, 42, 'او هغوی هغې ښځې ته وویل: «مونږ ستا د خبرې په سبب ایمان نه دی راوړی، بلکې مونږ په دې خاطر ایمان راوړو چې په خپله مو د هغه خبرې واورېدلې او په دې پوه شو چې هغه په رښتیا سره د نړۍ خلاصوونکی دی.» عیسی د یو مامور زوی ته شفا ورکوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_42.mp3', '', 1761754199, 1761754199),
(33412, 'John 4:43', 'John', 4, 43, 'دوه ورځې وروسته عیسی له هغه ځای نه روان شو او جلیل ته لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_43.mp3', '', 1761754199, 1761754199),
(33413, 'John 4:44', 'John', 4, 44, 'که څه هم عیسی په خپله شهادت ورکړی ؤ چې یو پیغمبر ته خلک په خپل وطن کې درناوی نه کوي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_44.mp3', '', 1761754199, 1761754199),
(33414, 'John 4:45', 'John', 4, 45, 'نو کله چې هغه جلیل ته ورسېده، خلکو ورته هرکلی ووایه. هغوی هم د فسحې په اختر کې اورشلیم ته تللي وو او هرڅه چې هغه په اختر کې په اورشلیم کې کړي وو، هغوی لیدلي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_45.mp3', '', 1761754199, 1761754199),
(33415, 'John 4:46', 'John', 4, 46, 'نو عیسی یوځل بیا په جلیل کې قانا نومي ځای ته چې هغه په کې اوبه په شرابو باندې بدلې کړې وې، لاړ. هلته د دولت یو مامور ؤ چې زوی یې په کپرناحوم کې ناروغه پروت ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_46.mp3', '', 1761754199, 1761754199),
(33416, 'John 4:47', 'John', 4, 47, 'کله چې هغه سړی خبر شو چې عیسی د یهودیې نه جلیل ته راغلی دی، نو ورته ورغی او زاري یې ورته وکړه چې کپرناحوم ته لاړ شي او زوی ته یې چې د مرګ په حال کې دی شفا ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_47.mp3', '', 1761754199, 1761754199),
(33417, 'John 4:48', 'John', 4, 48, 'عیسی هغه ته وویل: «ترڅو پورې چې تاسو معجزې او حیرانوونکي کارونه ونه وینئ، نو هېڅکله به ایمان رانه وړئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_48.mp3', '', 1761754199, 1761754199),
(33418, 'John 4:49', 'John', 4, 49, 'هغه مامور ورته وویل: «ښاغلیه، مخکې له دې چې زما زوی مړ شي راسره لاړ شه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_49.mp3', '', 1761754199, 1761754199),
(33419, 'John 4:50', 'John', 4, 50, 'عیسی وویل: «بېرته کور ته لاړ شه، زوی به دې ژوندی پاتې شي.» هغه سړي د عیسی په خبرو باندې باور وکړ او کورته لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_50.mp3', '', 1761754199, 1761754199),
(33420, 'John 4:51', 'John', 4, 51, 'هغه لا په لاره روان ؤ چې نوکران یې ورته په مخه ورغلل او ورته ویې ویل: «زوی دې ژوندی او روغ دی!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_51.mp3', '', 1761754199, 1761754199),
(33421, 'John 4:52', 'John', 4, 52, 'هغه ترې پوښتنه وکړه چې زوی مې کله روغ شو. هغوی ځواب ورکړ: «پرون ماسپښین یوه بجه هغه تبې پرېښود.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_52.mp3', '', 1761754199, 1761754199),
(33422, 'John 4:53', 'John', 4, 53, 'پلار یې پوه شو چې دا هماغه وخت ؤ چې عیسی ورته ویلي وو: «زوی به دې ژوندی پاتې شي.» نو هغه او د هغه ټولې کورنۍ ایمان راوړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_53.mp3', '', 1761754199, 1761754199),
(33423, 'John 4:54', 'John', 4, 54, 'دا د یهودیې نه جلیل ته د راتللو نه وروسته د عیسی دوهمه معجزه وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john4_verse_54.mp3', '', 1761754199, 1761754199),
(33424, 'Mark 13:1', 'Mark', 13, 1, 'کله چې عیسی د خدای د کور څخه وتلو، نو یو شاګرد یې ورته وویل: «ګوره استاذه، څومره ښکلې تیږې او لویې ودانۍ دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_1.mp3', '', 1761754199, 1761754199),
(33425, 'Mark 13:2', 'Mark', 13, 2, 'عیسی هغه ته وویل: «ته دا لویې لویې ودانۍ وینې؟ دلته به یوه تیږه هم د بلې تیږې دپاسه پاتې نه شي او ټولې به راونړیږي.» په ایمان کې تر اخره ټینګ پاتې شئ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_2.mp3', '', 1761754199, 1761754199),
(33426, 'Mark 13:3', 'Mark', 13, 3, 'عیسی د زیتون په غره کې د خدای کور ته مخامخ ناست ؤ، نو کله چې پطروس، یعقوب، یوحنا او اندریاس د هغه سره یوازې پاتې شول، نو د هغه څخه یې پوښتنه وکړه:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_3.mp3', '', 1761754199, 1761754199),
(33427, 'Mark 13:4', 'Mark', 13, 4, '«مونږ ته ووایه چې دا هرڅه به کله پېښ شي او د دې ټولو کارونو د پوره کېدلو نښه به څه وي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_4.mp3', '', 1761754199, 1761754199),
(33428, 'Mark 13:5', 'Mark', 13, 5, 'عیسی هغوی ته وویل: «پام کوئ چې څوک مو بې‌لارې نه کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_5.mp3', '', 1761754199, 1761754199),
(33429, 'Mark 13:6', 'Mark', 13, 6, 'ډېر به زما په نوم راشي او وایي به: ‹زه مسیح یم› او ډېر خلک به بې‌لارې کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_6.mp3', '', 1761754199, 1761754199),
(33430, 'Mark 13:7', 'Mark', 13, 7, 'کله چې تاسو د جنګونو په هکله خبرېږئ او د جنګونو اوازې واورئ، نو مه وارخطا کېږئ. دا شیان به خامخا پېښیږي. خو دا د دې معنی نه لري چې اخرنی وخت رارسېدلی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_7.mp3', '', 1761754199, 1761754199),
(33431, 'Mark 13:8', 'Mark', 13, 8, 'یو قوم به د بل قوم سره او یوه پاچاهي به د بلې پاچاهۍ سره جنګیږي. د نړۍ په ډېرو ځایونو کې به زلزلې وشي او قحطي به راشي او دا شیان به لکه د لنګون د دردونو د پیل کېدلو په شان وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_8.mp3', '', 1761754199, 1761754199),
(33432, 'Mark 13:9', 'Mark', 13, 9, 'خو تاسو په خپلو ځانونو باندې پام کوئ. تاسو به د محاکمې دپاره شوراګانو ته سپارل کېږئ، په کنیسو کې به وهل کېږئ او زما په خاطر به د والیانو او پاچاهانو په مخکې درول کېږئ، ترڅو د هغوی په مخکې شاهدي ورکړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_9.mp3', '', 1761754199, 1761754199),
(33433, 'Mark 13:10', 'Mark', 13, 10, 'خو مخکې له دې چې اخري وخت راورسیږي، نو اول باید ټولو قومونو ته زېری ورسول شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_10.mp3', '', 1761754199, 1761754199),
(33434, 'Mark 13:11', 'Mark', 13, 11, 'نو کله چې تاسو ونیول شئ او محکمې ته یووړل شئ، نو مخکې له مخکې مه پرېشانه کېږئ چې څه به وایئ بلکې څه چې په هغه ساعت کې د روح القدس په وسیله تاسو ته ویل کیږي ووایئ، ځکه چې هغه به ستاسو خبرې نه بلکې د روح القدس خبرې وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_11.mp3', '', 1761754199, 1761754199),
(33435, 'Mark 13:12', 'Mark', 13, 12, 'ورور به د ورور سره خیانت وکړي چې ووژل شي او پلار به د خپلو اولادونو سره. اولادونه به د خپلو میندو او پلرونو په خلاف راپورته شي او د هغوی د مړینې سبب به شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_12.mp3', '', 1761754199, 1761754199),
(33436, 'Mark 13:13', 'Mark', 13, 13, 'ټول خلک به زما د نوم له امله ستاسو څخه کرکه کوي. خو څوک چې تر اخره پورې ټینګ پاتې شي، هغه به خلاصون ومومي. لوی مصیبت (متي ۲۴‏:‌۱۵‌‏-‌۲۸ او لوقا ۲۱‏:‌۲۰‌‏-‌۲۴)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_13.mp3', '', 1761754199, 1761754199),
(33437, 'Mark 13:14', 'Mark', 13, 14, 'کله چې تاسو هغه نجس شی چې د بربادۍ سبب ګرځي، په هغه ځای کې ولاړ ووینئ چې باید هلته نه وي، (لوستونکی دې پوه شي چې د دې معنی څه ده) نو څوک چې په یهودیې کې وي هغه دې غرونو ته وتښتي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_14.mp3', '', 1761754199, 1761754199),
(33438, 'Mark 13:15', 'Mark', 13, 15, 'که څوک د بام په سر وي، نو هغه دې د کوم شي د وړلو دپاره لاندې راښکته نه شي او خپل کور ته دې نه ننوځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_15.mp3', '', 1761754199, 1761754199),
(33439, 'Mark 13:16', 'Mark', 13, 16, 'او که څوک په پټي کې وي، نو هغه دې د خپلې چپنې پسې بېرته کور ته نه ورځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_16.mp3', '', 1761754199, 1761754199),
(33440, 'Mark 13:17', 'Mark', 13, 17, 'افسوس د هغو ښځو په حال چې په هغو ورځو کې امیدوارې وي یا په هغو ښځو چې خپلو ماشومانو ته شیدې ورکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_17.mp3', '', 1761754199, 1761754199),
(33441, 'Mark 13:18', 'Mark', 13, 18, 'دعا کوئ چې دا شیان په ژمي کې پېښ نه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_18.mp3', '', 1761754199, 1761754199),
(33442, 'Mark 13:19', 'Mark', 13, 19, 'ځکه چې په هغو ورځو کې به داسې مصیبت رامنځته شي چې د کوم وخت نه چې خدای نړۍ پیدا کړې ده تر‌اوسه پورې نه دی راغلی او نه به بیا راشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_19.mp3', '', 1761754199, 1761754199),
(33443, 'Mark 13:20', 'Mark', 13, 20, 'که چېرې خدای دغه راتلونکې ورځې لنډې کړې نه وای، نو هېڅوک به ژوندی پاتې نه وای. خو هغه د خپلو غوره شویو خلکو په خاطر هغه ورځې لنډې کړې دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_20.mp3', '', 1761754199, 1761754199),
(33444, 'Mark 13:21', 'Mark', 13, 21, 'که په هغه وخت کې څوک تاسو ته ووایي: ‹ګورئ، مسیح دلته دی یا هلته دی.› نو باور ورباندې مه کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_21.mp3', '', 1761754199, 1761754199),
(33445, 'Mark 13:22', 'Mark', 13, 22, 'ځکه چې داسې کسان به پیدا شي چې په دروغو به دعوه کوي چې مسیح او پیغمبران دي او معجزې به وښایي او حیرانوونکي کارونه به کوي او که امکان ولري، نو د خدای غوره شوي خلک به هم بې‌لارې کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_22.mp3', '', 1761754199, 1761754199),
(33446, 'Mark 13:23', 'Mark', 13, 23, 'نو پام کوئ، تاسو مې له مخکې نه د دې ټولو شیانو نه خبر کړئ. د انسان د زوی راتګ (متي ۲۴‏:‌۲۹‌‏-‌۳۱ او لوقا ۲۱‏:‌۲۵‌‏-‌۲۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_23.mp3', '', 1761754199, 1761754199),
(33447, 'Mark 13:24', 'Mark', 13, 24, 'خو په هغو ورځو کې به د هغه مصیبت نه وروسته لمر تیاره شي او سپوږمۍ به نوره رڼا نه ورکوي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_24.mp3', '', 1761754199, 1761754199),
(33448, 'Mark 13:25', 'Mark', 13, 25, 'ستوري به د اسمان څخه راولویږي او اسماني موجودات به ولړزیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_25.mp3', '', 1761754199, 1761754199),
(33449, 'Mark 13:26', 'Mark', 13, 26, 'بیا به هغوی وویني چې د انسان زوی به د لوی قدرت او جلال سره په ورېځو کې راروان وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_26.mp3', '', 1761754199, 1761754199),
(33450, 'Mark 13:27', 'Mark', 13, 27, 'هغه به فرښتې ولېږي او د ټولې نړۍ د یو سر نه تر بل سر پورې به خپل غوره شوي خلک سره راټول کړي. د انځر د ونې نه عبرت اخیستل (متي ۲۴‏:‌۳۲‌‏-‌۳۵ او لوقا ۲۱‏:‌۲۹‌‏-‌۳۳)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_27.mp3', '', 1761754199, 1761754199),
(33451, 'Mark 13:28', 'Mark', 13, 28, 'د انځر د ونې څخه عبرت واخلئ. کله چې د هغې څانګې غوټۍ ونیسي او پاڼې وکړي، نو تاسو پوهېږئ چې اوړی رانژدې دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_28.mp3', '', 1761754199, 1761754199),
(33452, 'Mark 13:29', 'Mark', 13, 29, 'په همدې ډول کله چې تاسو دا شیان ووینئ، نو پوه شئ چې هغه وخت نژدې دی بلکې رارسېدلی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_29.mp3', '', 1761754199, 1761754199),
(33453, 'Mark 13:30', 'Mark', 13, 30, 'په یقین سره زه تاسو ته دا وایم چې دا نسل به تر هغې پورې له منځه لاړ نه شي، ترڅو دا ټولې پېښې رامنځته شوې نه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_30.mp3', '', 1761754199, 1761754199),
(33454, 'Mark 13:31', 'Mark', 13, 31, 'ځمکه او اسمان به له منځه لاړ شي، خو زما خبرې به هېڅکله له منځه لاړې نه شي. نامعلومه ورځ او وخت (متي ۲۴‏:‌۳۶‌‏-‌۴۴)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_31.mp3', '', 1761754199, 1761754199),
(33455, 'Mark 13:32', 'Mark', 13, 32, 'خو د هغې ورځې او هغه ساعت نه هېڅوک خبر نه دي، نه د اسمان فرښتې او نه زوی، یوازې پلار پرې خبر دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_32.mp3', '', 1761754199, 1761754199),
(33456, 'Mark 13:33', 'Mark', 13, 33, 'پام کوئ او بېداره اوسئ، ځکه چې تاسو نه پوهېږئ چې هغه وخت به کله راځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_33.mp3', '', 1761754199, 1761754199),
(33457, 'Mark 13:34', 'Mark', 13, 34, 'دا د هغه سړي په مثال دی چې د کور نه په سفر روان شي او خپلو نوکرانو ته اختیار ورکړي چې هر یو دې خپل کار وکړي او د دروازې ساتونکي ته حکم وکړي چې بېدار اوسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_34.mp3', '', 1761754199, 1761754199),
(33458, 'Mark 13:35', 'Mark', 13, 35, 'نو تاسو هم بېداره اوسئ، ځکه چې تاسو نه پوهېږئ چې د کور خاوند به کله راځي، ماښام یا په نیمه شپه کې، په چرګ بانګ یا د لمرخاته په وخت کې،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_35.mp3', '', 1761754199, 1761754199),
(33459, 'Mark 13:36', 'Mark', 13, 36, 'هسې نه چې هغه ناڅاپه راشي او تاسو په خوب ویده وویني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark13_verse_36.mp3', '', 1761754199, 1761754199),
