(33500, 'Acts 13:13', 'Acts', 13, 13, 'پولوس او د هغه ملګري د پافوس څخه روان شول او په کشتۍ کې پرجې ته چې په پمفیلیه کې ده، لاړل. خو یوحنا د هغوی څخه بېل شو او بېرته اورشلیم ته ستون شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_13.mp3', '', 1761754199, 1761754199),
(33501, 'Acts 13:14', 'Acts', 13, 14, 'پولوس او برناباس د پرجې څخه روان شول او انطاکیې ته چې په پیسیدیه کې ده، ورسېدل. د سبت په ورځ هغوی کنیسې ته لاړل او هلته کښېناستل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_14.mp3', '', 1761754199, 1761754199),
(33502, 'Acts 13:15', 'Acts', 13, 15, 'د تورات او پیغمبرانو د لیکنو د لوستلو څخه وروسته د کنیسې مشرانو هغوی ته دا پیغام ورولېږه: «ای ورونو، که چېرې تاسو د خلکو د هڅولو دپاره کوم پیغام لرئ، نو هغه ووایئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_15.mp3', '', 1761754199, 1761754199),
(33503, 'Acts 13:16', 'Acts', 13, 16, 'پولوس پاڅېده، په لاس یې اشاره وکړه او ویې ویل: «ای د اسراییلو خلکو او ای غیریهودیانو چې له خدایه وېرېږئ، زما خبرو ته غوږ ونیسئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_16.mp3', '', 1761754199, 1761754199),
(33504, 'Acts 13:17', 'Acts', 13, 17, 'د اسراییلو د خلکو خدای زمونږ نیکونه غوره کړل او کوم وخت چې هغوی په مصر کې د پردیو په شان اوسېدل، نو د هغوی څخه یې یو لوی قوم جوړ کړ. بیا یې په خپل لوی قدرت سره هغوی د مصر څخه راوویستل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_17.mp3', '', 1761754199, 1761754199),
(33505, 'Acts 13:18', 'Acts', 13, 18, 'او نژدې څلوېښت کاله یې په دښته کې د هغوی چلند وزغملو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_18.mp3', '', 1761754199, 1761754199),
(33506, 'Acts 13:19', 'Acts', 13, 19, 'هغه په کنعان کې اووه قومونه له منځه یووړل او د هغوی خاوره یې د میراث په توګه خپل قوم ته ورکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_19.mp3', '', 1761754199, 1761754199),
(33507, 'Acts 13:20', 'Acts', 13, 20, 'دا هرڅه نژدې څلور سوه او پنځوس کالو کې وشول. له هغې وروسته یې د سموییل پیغمبر تر زمانې پورې د هغوی دپاره قاضیان وټاکل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_20.mp3', '', 1761754199, 1761754199),
(33508, 'Acts 13:21', 'Acts', 13, 21, 'او کله چې هغوی د خپل ځان دپاره پاچا وغوښت، نو خدای ورته د قیس زوی شاوول چې د بنیامین د قبیلې څخه ؤ، ورکړ او هغه څلوېښت کاله پاچاهي وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_21.mp3', '', 1761754199, 1761754199),
(33509, 'Acts 13:22', 'Acts', 13, 22, 'کله چې خدای شاوول لېرې کړ، نو داود یې د اسراییلو پاچا کړ. خدای د داود په هکله داسې وویل: ‹ما ولیدل چې د یسي زوی داود داسې سړی دی چې زما د زړه نه خبر دی او هرڅه چې زه وغواړم هغه به یې سرته رسوي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_22.mp3', '', 1761754199, 1761754199),
(33510, 'Acts 13:23', 'Acts', 13, 23, 'نو د همدې داود د نسل څخه خدای د خپلې وعدې له مخې عیسی د اسراییلو د قوم د خلاصوونکي په توګه راولېږه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts13_verse_23.mp3', '', 1761754199, 1761754199);